BEGIN
    IF NEW.venue_id IS DISTINCT FROM OLD.venue_id THEN
        IF OLD.stage IN ('books_out','closed','closed_duplicate') THEN
            RAISE EXCEPTION 'venue change forbidden after books were issued'
                USING ERRCODE = 'check_violation';
        END IF;
        IF OLD.kind IN ('social','debt')
           AND OLD.stage NOT IN ('draft','on_review','needs_rework','archived') THEN
            RAISE EXCEPTION 'venue change forbidden after booking link for % application', OLD.kind
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END

DECLARE
    venue_limit integer;
BEGIN
    SELECT max_capacity INTO venue_limit
    FROM lectures.venue_capacity_limits
    WHERE venue_id = NEW.venue_id;
    IF venue_limit IS NULL THEN
        RAISE EXCEPTION 'venue % has no capacity limit', NEW.venue_id;
    END IF;
    IF NEW.capacity > venue_limit THEN
        RAISE EXCEPTION 'event capacity % exceeds venue % limit %', NEW.capacity, NEW.venue_id, venue_limit;
    END IF;
    RETURN NEW;
END;

DECLARE
    c partners.contracts%ROWTYPE;
    exposure numeric(12,2);
BEGIN
    SELECT * INTO c FROM partners.contracts WHERE id = NEW.contract_id FOR UPDATE;
    IF NEW.on_credit AND NOT c.credit_allowed THEN
        RAISE EXCEPTION 'contract % does not allow credit deals', c.number
            USING ERRCODE = 'check_violation';
    END IF;
    SELECT coalesce(sum(amount), 0) INTO exposure
    FROM partners.deals
    WHERE contract_id = NEW.contract_id AND on_credit AND paid_at IS NULL AND status <> 'cancelled';
    IF exposure > c.credit_limit THEN
        RAISE EXCEPTION 'credit limit of contract % exceeded, new deals are blocked', c.number
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.on_credit AND exposure + NEW.amount > c.credit_limit THEN
        RAISE EXCEPTION 'deal exceeds credit limit of contract %: % + % > %',
            c.number, exposure, NEW.amount, c.credit_limit
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END

DECLARE
    p partners.partners%ROWTYPE;
BEGIN
    IF NEW.status = 'active' AND OLD.status = 'draft' THEN
        SELECT * INTO p FROM partners.partners WHERE id = NEW.partner_id;
        IF p.inn IS NULL OR p.kpp IS NULL OR coalesce(btrim(p.legal_name), '') = '' THEN
            RAISE EXCEPTION 'partner % has incomplete requisites', p.id
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END

DECLARE
    ev record;
    taken integer;
BEGIN
    SELECT capacity, status INTO ev FROM lectures.events WHERE id = NEW.event_id FOR UPDATE;
    IF ev.status <> 'scheduled' THEN
        RAISE EXCEPTION 'event % is not open for registration', NEW.event_id;
    END IF;
    SELECT count(*) INTO taken
    FROM lectures.registrations
    WHERE event_id = NEW.event_id AND status = 'confirmed' AND id <> NEW.id;
    IF taken >= ev.capacity THEN
        RAISE EXCEPTION 'event % is full', NEW.event_id;
    END IF;
    RETURN NEW;
END;

DECLARE
    site_max int;
    taken int;
BEGIN
    SELECT max_shift_staff INTO site_max FROM staff.sites WHERE id = NEW.site_id;
    IF NEW.capacity > site_max THEN
        RAISE EXCEPTION 'shift capacity % exceeds site maximum %', NEW.capacity, site_max
            USING ERRCODE = 'check_violation';
    END IF;
    IF TG_OP = 'UPDATE' THEN
        SELECT count(*) INTO taken FROM staff.shift_members
            WHERE shift_id = NEW.id AND status = 'assigned';
        IF taken > NEW.capacity THEN
            RAISE EXCEPTION 'shift % already has % staff', NEW.id, taken
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END

DECLARE
    cap int;
    taken int;
BEGIN
    IF NEW.status <> 'assigned' THEN
        RETURN NEW;
    END IF;
    SELECT capacity INTO cap FROM staff.shifts WHERE id = NEW.shift_id FOR UPDATE;
    SELECT count(*) INTO taken FROM staff.shift_members
        WHERE shift_id = NEW.shift_id AND status = 'assigned' AND id <> NEW.id;
    IF taken >= cap THEN
        RAISE EXCEPTION 'shift % is full: % staff', NEW.shift_id, cap
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END

BEGIN
    IF EXISTS (
        SELECT 1 FROM staff.shifts
        WHERE site_id = NEW.id AND status = 'planned' AND capacity > NEW.max_shift_staff
    ) THEN
        RAISE EXCEPTION 'site % has planned shifts above % staff', NEW.id, NEW.max_shift_staff
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END

DECLARE
    lim int;
BEGIN
    SELECT max_capacity INTO lim FROM scheduling.venue_limits WHERE venue_id = NEW.venue_id;
    IF lim IS NULL THEN
        RAISE EXCEPTION 'no capacity limit for venue %', NEW.venue_id USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.capacity > lim THEN
        RAISE EXCEPTION 'slot capacity % exceeds venue maximum %', NEW.capacity, lim
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END

DECLARE
    current_venue int;
BEGIN
    SELECT venue_id INTO current_venue FROM inventory.copies WHERE id = NEW.copy_id;
    IF current_venue IS DISTINCT FROM NEW.from_venue_id THEN
        RAISE EXCEPTION 'copy % is not at venue %', NEW.copy_id, NEW.from_venue_id
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END

BEGIN
    IF NEW.status = 'cancelled' AND OLD.status = 'active' AND EXISTS (
        SELECT 1 FROM billing.payments p
        WHERE p.invoice_id = OLD.id AND p.unlinked_at IS NULL AND NOT p.refunded
    ) THEN
        RAISE EXCEPTION 'invoice % has a linked payment', OLD.id USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END

BEGIN
    IF NEW.amount <> OLD.amount OR NEW.rate_pct <> OLD.rate_pct OR NEW.base_amount <> OLD.base_amount THEN
        RAISE EXCEPTION 'accrued commission % cannot be recalculated', OLD.id
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END

BEGIN
    IF NEW.sphere_id <> OLD.sphere_id OR NEW.representative_id <> OLD.representative_id THEN
        RAISE EXCEPTION 'sphere and representative of an application cannot be changed'
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END

BEGIN
    RAISE EXCEPTION 'chat messages cannot be edited or deleted' USING ERRCODE = 'check_violation';
END

DECLARE
    invoice_status text;
BEGIN
    SELECT status INTO invoice_status FROM halls.hall_invoices WHERE id = NEW.invoice_id;
    IF invoice_status IS DISTINCT FROM 'open' THEN
        RAISE EXCEPTION 'счёт % закрыт, платёж не принимается', NEW.invoice_id
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;

BEGIN
    IF (SELECT status FROM billing.invoices WHERE id = NEW.invoice_id) <> 'active' THEN
        RAISE EXCEPTION 'payment cannot be linked to a cancelled invoice' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END

BEGIN
    IF NEW.venue_id IS DISTINCT FROM OLD.venue_id THEN
        IF OLD.state = 'on_loan' OR EXISTS (
            SELECT 1 FROM inventory.ill_loans l WHERE l.copy_id = OLD.id AND l.status = 'out'
        ) THEN
            RAISE EXCEPTION 'copy % is on loan and cannot change venue', OLD.inventory_no
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END

BEGIN
    IF OLD.state = 'written_off' THEN
        RAISE EXCEPTION 'copy % is written off', OLD.inventory_no USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END

BEGIN
    IF OLD.status IN ('confirmed', 'held') AND NEW.venue_id IS DISTINCT FROM OLD.venue_id THEN
        RAISE EXCEPTION 'бронь % подтверждена, площадку сменить нельзя', OLD.id
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;

BEGIN
    IF NEW.commission_pct IS DISTINCT FROM OLD.commission_pct THEN
        INSERT INTO partners.contract_history (contract_id, field, old_value, new_value)
        VALUES (NEW.id, 'commission_pct', OLD.commission_pct::text, NEW.commission_pct::text);
    END IF;
    IF NEW.credit_allowed IS DISTINCT FROM OLD.credit_allowed THEN
        INSERT INTO partners.contract_history (contract_id, field, old_value, new_value)
        VALUES (NEW.id, 'credit_allowed', OLD.credit_allowed::text, NEW.credit_allowed::text);
    END IF;
    IF NEW.credit_limit IS DISTINCT FROM OLD.credit_limit THEN
        INSERT INTO partners.contract_history (contract_id, field, old_value, new_value)
        VALUES (NEW.id, 'credit_limit', OLD.credit_limit::text, NEW.credit_limit::text);
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status THEN
        INSERT INTO partners.contract_history (contract_id, field, old_value, new_value)
        VALUES (NEW.id, 'status', OLD.status, NEW.status);
    END IF;
    RETURN NULL;
END

BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO halls.hall_booking_history (booking_id, old_status, new_status)
        VALUES (NEW.id, NULL, NEW.status);
    ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
        INSERT INTO halls.hall_booking_history (booking_id, old_status, new_status)
        VALUES (NEW.id, OLD.status, NEW.status);
    END IF;
    RETURN NULL;
END;

BEGIN
    IF OLD.status IN ('sent', 'cancelled') AND NEW.status <> OLD.status THEN
        RAISE EXCEPTION 'кампания % уже в статусе %', OLD.id, OLD.status;
    END IF;
    RETURN NEW;
END;

BEGIN
    IF OLD.sent_at IS NOT NULL AND NEW.body IS DISTINCT FROM OLD.body THEN
        RAISE EXCEPTION 'письмо % уже отправлено, текст менять нельзя', OLD.id;
    END IF;
    RETURN NEW;
END;

BEGIN
    NEW.email := lower(trim(NEW.email));
    RETURN NEW;
END;

BEGIN
    UPDATE subscriptions.invoices
       SET paid_total = paid_total + NEW.amount
     WHERE id = NEW.invoice_id;
    RETURN NULL;
END;

DECLARE
    inv subscriptions.invoices%ROWTYPE;
BEGIN
    SELECT * INTO inv FROM subscriptions.invoices WHERE id = NEW.invoice_id FOR UPDATE;
    IF inv.status <> 'open' THEN
        RAISE EXCEPTION 'invoice % is not open', NEW.invoice_id;
    END IF;
    IF inv.paid_total + NEW.amount > inv.amount THEN
        RAISE EXCEPTION 'payment exceeds invoice % balance', NEW.invoice_id;
    END IF;
    RETURN NEW;
END;

BEGIN
    IF EXISTS (SELECT 1 FROM reports.report_runs r WHERE r.definition_id = OLD.id) THEN
        RAISE EXCEPTION 'у отчёта % уже есть запуски, тип менять нельзя', OLD.code
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;

BEGIN
    IF OLD.status IN ('completed', 'failed', 'cancelled') THEN
        RAISE EXCEPTION 'запуск % уже завершён (%), изменять его нельзя', OLD.id, OLD.status
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;

BEGIN
    IF NEW.status = OLD.status THEN
        RETURN NEW;
    END IF;
    IF NOT (
        (OLD.status = 'requested' AND NEW.status IN ('running', 'failed', 'cancelled'))
        OR (OLD.status = 'running' AND NEW.status IN ('completed', 'failed'))
    ) THEN
        RAISE EXCEPTION 'недопустимый переход запуска %: % -> %', OLD.id, OLD.status, NEW.status
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;

BEGIN
    IF NEW.status IS DISTINCT FROM OLD.status THEN
        INSERT INTO subscriptions.status_history (subscription_id, old_status, new_status)
        VALUES (NEW.id, OLD.status, NEW.status);
    END IF;
    RETURN NULL;
END;

BEGIN
    IF OLD.status IN ('expired', 'closed_duplicate') AND NEW.status <> OLD.status THEN
        RAISE EXCEPTION 'subscription % is closed (%)', OLD.id, OLD.status;
    END IF;
    RETURN NEW;
END;

BEGIN
    IF NEW.updated_at IS NOT DISTINCT FROM OLD.updated_at THEN
        NEW.updated_at := now();
    END IF;
    RETURN NEW;
END;
